-- C-owned schema 1. Contract major 2 is unrelated to database migration number.
-- Apply atomically to an empty database; back up an existing library before later migrations.
BEGIN IMMEDIATE;
PRAGMA foreign_keys = ON;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE entities(entity_id TEXT PRIMARY KEY, kind TEXT NOT NULL, revision_id TEXT, entity_seq INTEGER NOT NULL DEFAULT 0 CHECK(entity_seq>=0), lifecycle TEXT NOT NULL DEFAULT 'active' CHECK(lifecycle IN ('active','removed','deleted')));
CREATE TABLE revisions(revision_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entities(entity_id), content_hash TEXT NOT NULL CHECK(length(content_hash)=64), body_json TEXT CHECK(body_json IS NULL OR json_valid(body_json)), committed_at TEXT NOT NULL);
CREATE TABLE revision_parents(revision_id TEXT REFERENCES revisions(revision_id), parent_revision_id TEXT REFERENCES revisions(revision_id), PRIMARY KEY(revision_id,parent_revision_id));
CREATE TABLE courses(course_id TEXT PRIMARY KEY REFERENCES entities(entity_id), name TEXT NOT NULL);
CREATE TABLE lessons(lesson_id TEXT PRIMARY KEY REFERENCES entities(entity_id), course_id TEXT NOT NULL REFERENCES courses(course_id), title TEXT NOT NULL, actual_date TEXT, timezone TEXT NOT NULL DEFAULT 'Asia/Shanghai', requested_language_tier INTEGER NOT NULL DEFAULT 3 CHECK(requested_language_tier BETWEEN 1 AND 5), last_recording_tier INTEGER CHECK(last_recording_tier BETWEEN 1 AND 5), attachment_set_revision TEXT NOT NULL, fact_set_revision TEXT);
CREATE TABLE recording_sessions(recording_id TEXT PRIMARY KEY REFERENCES entities(entity_id), lesson_id TEXT REFERENCES lessons(lesson_id), assignment_epoch INTEGER NOT NULL DEFAULT 0 CHECK(assignment_epoch>=0), state TEXT NOT NULL CHECK(state IN ('starting','recording','paused','stopping','stopped','interrupted','failed')), capture_language_tier INTEGER NOT NULL CHECK(capture_language_tier BETWEEN 1 AND 5), timeline_origin TEXT NOT NULL, durable_watermark_ms INTEGER NOT NULL DEFAULT 0 CHECK(durable_watermark_ms>=0));
CREATE UNIQUE INDEX one_active_capture ON recording_sessions((1)) WHERE state IN ('starting','recording','paused','stopping');
CREATE TABLE resources(resource_id TEXT PRIMARY KEY, relative_path TEXT NOT NULL CHECK(relative_path NOT LIKE '/%' AND relative_path NOT LIKE '%..%' AND relative_path NOT LIKE '%\%'), sha256 TEXT NOT NULL CHECK(length(sha256)=64), media_type TEXT NOT NULL, byte_length INTEGER NOT NULL CHECK(byte_length>=0), state TEXT NOT NULL CHECK(state IN ('staged','ready','deleted')));
CREATE TABLE resource_owners(resource_id TEXT REFERENCES resources(resource_id), owner_entity_id TEXT REFERENCES entities(entity_id), PRIMARY KEY(resource_id,owner_entity_id));
CREATE TABLE audio_assets(audio_asset_id TEXT PRIMARY KEY REFERENCES entities(entity_id), recording_id TEXT NOT NULL REFERENCES recording_sessions(recording_id), resource_id TEXT NOT NULL REFERENCES resources(resource_id), origin TEXT NOT NULL CHECK(origin IN ('original','derived')), tracks_json TEXT NOT NULL CHECK(json_valid(tracks_json)), decode_status TEXT NOT NULL);
CREATE TABLE time_mappings(mapping_revision_id TEXT PRIMARY KEY, derived_asset_id TEXT NOT NULL REFERENCES audio_assets(audio_asset_id), segments_json TEXT NOT NULL CHECK(json_valid(segments_json)));
CREATE TABLE audio_spans(audio_span_id TEXT PRIMARY KEY REFERENCES entities(entity_id), recording_id TEXT NOT NULL REFERENCES recording_sessions(recording_id), asset_id TEXT REFERENCES audio_assets(audio_asset_id), track_id TEXT, start_frame INTEGER, end_frame INTEGER, start_ms INTEGER NOT NULL CHECK(start_ms>=0), end_ms INTEGER NOT NULL CHECK(end_ms>=start_ms), mapping_revision_id TEXT REFERENCES time_mappings(mapping_revision_id), coverage_status TEXT NOT NULL CHECK(coverage_status IN ('captured','silence_observed','capture_gap','decode_unknown')), asr_coverage TEXT NOT NULL CHECK(asr_coverage IN ('unsubmitted','pending','provisional','final','failed','uncertain')), CHECK(coverage_status NOT IN ('captured','silence_observed') OR (asset_id IS NOT NULL AND track_id IS NOT NULL AND mapping_revision_id IS NOT NULL AND start_frame IS NOT NULL AND end_frame>=start_frame)));
CREATE TABLE recording_alignments(alignment_id TEXT PRIMARY KEY, recording_id TEXT NOT NULL REFERENCES recording_sessions(recording_id), lesson_id TEXT REFERENCES lessons(lesson_id), start_ms INTEGER NOT NULL, end_ms INTEGER NOT NULL CHECK(end_ms>=start_ms), lesson_offset_ms INTEGER, evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)), confirmation TEXT NOT NULL);
CREATE TABLE raw_utterances(utterance_id TEXT PRIMARY KEY REFERENCES entities(entity_id), recording_id TEXT NOT NULL REFERENCES recording_sessions(recording_id), ordinal INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('provisional','final')), text TEXT, revision_id TEXT NOT NULL, speaker_ref TEXT, remote_binding_json TEXT NOT NULL CHECK(json_valid(remote_binding_json)), audio_spans_json TEXT NOT NULL CHECK(json_valid(audio_spans_json)));
CREATE TRIGGER final_raw_is_immutable BEFORE UPDATE OF text,revision_id,state ON raw_utterances WHEN OLD.state='final' AND ((NEW.text IS NOT OLD.text AND NEW.text IS NOT NULL) OR NEW.revision_id<>OLD.revision_id OR NEW.state<>'final') BEGIN SELECT RAISE(ABORT,'stable raw is immutable'); END;
CREATE TRIGGER raw_null_requires_tombstone BEFORE UPDATE OF text ON raw_utterances WHEN NEW.text IS NULL AND NOT EXISTS(SELECT 1 FROM entities WHERE entity_id=OLD.utterance_id AND lifecycle='deleted') BEGIN SELECT RAISE(ABORT,'purge requires tombstone'); END;
CREATE TABLE secondary_segments(secondary_id TEXT PRIMARY KEY REFERENCES entities(entity_id), recording_id TEXT NOT NULL REFERENCES recording_sessions(recording_id), revision_id TEXT NOT NULL, raw_refs_json TEXT NOT NULL CHECK(json_valid(raw_refs_json)), ordered_spans_json TEXT NOT NULL CHECK(json_valid(ordered_spans_json)), text TEXT, generation_revision TEXT NOT NULL);
CREATE TABLE facts(fact_id TEXT PRIMARY KEY REFERENCES entities(entity_id), lesson_id TEXT NOT NULL REFERENCES lessons(lesson_id), proposition_json TEXT NOT NULL CHECK(json_valid(proposition_json)), fact_set_revision TEXT NOT NULL);
CREATE TABLE notes(note_id TEXT PRIMARY KEY REFERENCES entities(entity_id), lesson_id TEXT NOT NULL REFERENCES lessons(lesson_id), fact_set_revision TEXT NOT NULL, object_graph_json TEXT NOT NULL CHECK(json_valid(object_graph_json)));
CREATE TABLE note_facts(note_id TEXT REFERENCES notes(note_id), fact_id TEXT REFERENCES facts(fact_id), PRIMARY KEY(note_id,fact_id));
CREATE TABLE language_variants(variant_id TEXT PRIMARY KEY REFERENCES entities(entity_id), note_id TEXT NOT NULL REFERENCES notes(note_id), tier INTEGER NOT NULL CHECK(tier BETWEEN 1 AND 5), fact_set_revision TEXT NOT NULL, presentation_revision TEXT NOT NULL, sync_status TEXT NOT NULL CHECK(sync_status IN ('ready','generating','stale','failed')), UNIQUE(note_id,tier));
CREATE TABLE presentation_meta(target_id TEXT PRIMARY KEY REFERENCES entities(entity_id), generation_completed_at TEXT, evidence_cutoff_json TEXT NOT NULL CHECK(json_valid(evidence_cutoff_json)), requested_tier INTEGER, actual_tier INTEGER, sync_status TEXT NOT NULL);
CREATE TABLE source_edges(edge_id TEXT PRIMARY KEY, from_entity_id TEXT NOT NULL REFERENCES entities(entity_id), from_revision_id TEXT NOT NULL, from_selector_json TEXT NOT NULL CHECK(json_valid(from_selector_json)), to_entity_id TEXT NOT NULL REFERENCES entities(entity_id), to_revision_id TEXT NOT NULL, to_ref_json TEXT NOT NULL CHECK(json_valid(to_ref_json)), role TEXT NOT NULL, availability TEXT NOT NULL, freshness TEXT NOT NULL, snapshot_id TEXT NOT NULL);
CREATE INDEX source_edges_incoming ON source_edges(to_entity_id);
CREATE TABLE user_patches(patch_id TEXT PRIMARY KEY, target_id TEXT NOT NULL REFERENCES entities(entity_id), base_revision TEXT NOT NULL, selector_json TEXT NOT NULL CHECK(json_valid(selector_json)), before_hash TEXT NOT NULL, operation TEXT NOT NULL, after_value_json TEXT NOT NULL CHECK(json_valid(after_value_json)), intent TEXT NOT NULL, undo_group_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE delete_intents(intent_id TEXT PRIMARY KEY, target_id TEXT NOT NULL REFERENCES entities(entity_id), semantic_key TEXT, scope_json TEXT NOT NULL CHECK(json_valid(scope_json)), base_sources_json TEXT NOT NULL CHECK(json_valid(base_sources_json)), undo_group_id TEXT NOT NULL, undone INTEGER NOT NULL DEFAULT 0 CHECK(undone IN (0,1)));
CREATE TABLE edit_leases(view_id TEXT NOT NULL, target_id TEXT NOT NULL REFERENCES entities(entity_id), lease_epoch INTEGER NOT NULL, selectors_json TEXT NOT NULL CHECK(json_valid(selectors_json)), composition_active INTEGER NOT NULL CHECK(composition_active IN (0,1)), draft_revision TEXT, PRIMARY KEY(view_id,target_id));
CREATE TABLE correction_suggestions(suggestion_id TEXT PRIMARY KEY, secondary_id TEXT NOT NULL REFERENCES secondary_segments(secondary_id), source_revision TEXT NOT NULL, body_json TEXT NOT NULL CHECK(json_valid(body_json)), state TEXT NOT NULL CHECK(state IN ('pending','accepted','rejected','obsolete')));
CREATE TABLE proposals(proposal_id TEXT PRIMARY KEY, target_id TEXT NOT NULL REFERENCES entities(entity_id), snapshot_id TEXT NOT NULL, base_revision TEXT NOT NULL, body_json TEXT CHECK(body_json IS NULL OR json_valid(body_json)), publication TEXT NOT NULL CHECK(publication IN ('pending','committed','review_required','rejected_stale')));
CREATE TABLE materials(material_id TEXT PRIMARY KEY REFERENCES entities(entity_id), source_version_id TEXT NOT NULL, resource_id TEXT NOT NULL REFERENCES resources(resource_id), file_type TEXT NOT NULL, display_name TEXT NOT NULL);
CREATE TABLE material_attachments(attachment_id TEXT PRIMARY KEY REFERENCES entities(entity_id), material_id TEXT NOT NULL REFERENCES materials(material_id), lesson_id TEXT REFERENCES lessons(lesson_id), course_id TEXT REFERENCES courses(course_id), purpose TEXT NOT NULL CHECK(purpose IN ('textbook','courseware','reference')), pages_json TEXT NOT NULL CHECK(json_valid(pages_json)), lifecycle TEXT NOT NULL CHECK(lifecycle IN ('active','removed','deleted')));
CREATE TABLE parse_versions(parse_version_id TEXT PRIMARY KEY, material_id TEXT NOT NULL REFERENCES materials(material_id), source_version_id TEXT NOT NULL, parent_parse_version_id TEXT, format_version TEXT NOT NULL, engine_build TEXT NOT NULL, manifest_json TEXT CHECK(manifest_json IS NULL OR json_valid(manifest_json)), content_hash TEXT NOT NULL, completion TEXT NOT NULL CHECK(completion IN ('partial','complete','failed')));
CREATE TABLE material_corrections(correction_id TEXT PRIMARY KEY, material_id TEXT NOT NULL REFERENCES materials(material_id), base_parse_version_id TEXT NOT NULL REFERENCES parse_versions(parse_version_id), body_json TEXT NOT NULL CHECK(json_valid(body_json)), replay_status TEXT NOT NULL CHECK(replay_status IN ('applied','conflict','unmatched')));
CREATE TABLE definitions(definition_id TEXT PRIMARY KEY REFERENCES entities(entity_id), concept_id TEXT NOT NULL, lesson_id TEXT NOT NULL REFERENCES lessons(lesson_id), scope_id TEXT NOT NULL, body_json TEXT NOT NULL CHECK(json_valid(body_json)));
CREATE TABLE symbol_bindings(binding_id TEXT PRIMARY KEY REFERENCES entities(entity_id), definition_id TEXT NOT NULL REFERENCES definitions(definition_id), scope_id TEXT NOT NULL, body_json TEXT NOT NULL CHECK(json_valid(body_json)));
CREATE TABLE input_snapshots(snapshot_id TEXT PRIMARY KEY, parent_snapshot_id TEXT REFERENCES input_snapshots(snapshot_id), contract_version TEXT NOT NULL, body_json TEXT CHECK(body_json IS NULL OR json_valid(body_json)), content_hash TEXT NOT NULL, available_at TEXT NOT NULL);
CREATE TABLE tasks(task_id TEXT PRIMARY KEY, kind TEXT NOT NULL, target_id TEXT NOT NULL, snapshot_id TEXT NOT NULL REFERENCES input_snapshots(snapshot_id), state TEXT NOT NULL CHECK(state IN ('queued','running','waiting_network','waiting_input','paused','retry_wait','cancel_requested','interrupted','succeeded','failed','cancelled','superseded')), priority INTEGER NOT NULL CHECK(priority BETWEEN 0 AND 4), attempt INTEGER NOT NULL CHECK(attempt>0), deadline_at TEXT, idempotency_key TEXT NOT NULL, checkpoint_json TEXT NOT NULL CHECK(json_valid(checkpoint_json)), safe_error_json TEXT CHECK(safe_error_json IS NULL OR json_valid(safe_error_json)), model_id TEXT, credential_ref TEXT, region TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK((model_id IS NULL AND credential_ref IS NULL AND region IS NULL) OR (region='cn-beijing' AND ((model_id='qwen-audio-3.1-asr-flash-streaming' AND credential_ref='bailian_beijing_asr_streaming') OR (model_id='qwen-audio-3.1-asr-flash-filetrans' AND credential_ref='bailian_beijing_asr_filetrans') OR (model_id='decision-model-preview' AND credential_ref='bailian_beijing_progress') OR (model_id='qwen3.8-flash' AND credential_ref='bailian_beijing_multimodal')))));
CREATE TABLE remote_bindings(task_id TEXT NOT NULL REFERENCES tasks(task_id), attempt INTEGER NOT NULL, provider_task_id TEXT NOT NULL, binding_json TEXT NOT NULL CHECK(json_valid(binding_json)), PRIMARY KEY(task_id,attempt,provider_task_id));
CREATE TABLE idempotency(actor_id TEXT NOT NULL, command_name TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, response_json TEXT NOT NULL CHECK(json_valid(response_json)), PRIMARY KEY(actor_id,command_name,idempotency_key));
CREATE TABLE outbox(global_seq INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL UNIQUE, scope_json TEXT NOT NULL CHECK(json_valid(scope_json)), event_type TEXT NOT NULL, entity_id TEXT NOT NULL, entity_seq INTEGER NOT NULL, revision_id TEXT NOT NULL, cause_command_id TEXT, task_id TEXT, committed_at TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE TABLE views(view_id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL REFERENCES lessons(lesson_id), target_json TEXT NOT NULL CHECK(json_valid(target_json)), host_window_id TEXT NOT NULL, view_revision TEXT NOT NULL, state_json TEXT NOT NULL CHECK(json_valid(state_json)));
CREATE TABLE view_transfers(transfer_id TEXT PRIMARY KEY, view_id TEXT NOT NULL REFERENCES views(view_id), source_window_id TEXT NOT NULL, target_window_id TEXT NOT NULL, base_view_revision TEXT NOT NULL, lease_epoch INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('preparing','committed','rolled_back')));
CREATE TABLE visualizations(object_id TEXT PRIMARY KEY REFERENCES entities(entity_id), note_id TEXT NOT NULL REFERENCES notes(note_id), revision_id TEXT NOT NULL, template_id TEXT NOT NULL, template_version TEXT NOT NULL, registry_revision TEXT NOT NULL, semantic_key TEXT NOT NULL, manual_copy INTEGER NOT NULL DEFAULT 0, parameters_hash TEXT NOT NULL, description_json TEXT NOT NULL CHECK(json_valid(description_json)), generation_status TEXT NOT NULL, validation_json TEXT NOT NULL CHECK(json_valid(validation_json)));
CREATE UNIQUE INDEX visualization_auto_semantic ON visualizations(note_id,semantic_key) WHERE manual_copy=0;
CREATE TABLE visibility_barrier(singleton INTEGER PRIMARY KEY CHECK(singleton=1), visibility_epoch INTEGER NOT NULL);
INSERT INTO visibility_barrier VALUES(1,0);
CREATE TABLE tombstones(entity_id TEXT PRIMARY KEY, deleted_at TEXT NOT NULL, visibility_epoch INTEGER NOT NULL);
CREATE TRIGGER deletion_barrier AFTER UPDATE OF lifecycle ON entities WHEN NEW.lifecycle='deleted' AND OLD.lifecycle<>'deleted' BEGIN UPDATE visibility_barrier SET visibility_epoch=visibility_epoch+1 WHERE singleton=1; INSERT OR REPLACE INTO tombstones VALUES(NEW.entity_id,strftime('%Y-%m-%dT%H:%M:%fZ','now'),(SELECT visibility_epoch FROM visibility_barrier WHERE singleton=1)); DELETE FROM search_units WHERE owner_entity_id=NEW.entity_id; END;
CREATE TRIGGER attachment_barrier AFTER UPDATE OF lifecycle ON material_attachments WHEN NEW.lifecycle<>OLD.lifecycle BEGIN UPDATE visibility_barrier SET visibility_epoch=visibility_epoch+1 WHERE singleton=1; END;
CREATE TRIGGER assignment_barrier AFTER UPDATE OF assignment_epoch ON recording_sessions WHEN NEW.assignment_epoch<>OLD.assignment_epoch BEGIN UPDATE visibility_barrier SET visibility_epoch=visibility_epoch+1 WHERE singleton=1; END;
CREATE TABLE search_units(search_unit_id TEXT PRIMARY KEY, owner_entity_id TEXT NOT NULL REFERENCES entities(entity_id), revision_id TEXT NOT NULL, content_hash TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('material','note','raw','secondary')), visible_tier INTEGER, field_path TEXT NOT NULL, display_text TEXT NOT NULL, normalized_text TEXT NOT NULL, normalization_profile TEXT NOT NULL, offset_map_json TEXT NOT NULL CHECK(json_valid(offset_map_json)), anchor_json TEXT NOT NULL CHECK(json_valid(anchor_json)), equivalence_group_id TEXT, source_role TEXT NOT NULL, index_generation INTEGER NOT NULL);
CREATE INDEX search_owner ON search_units(owner_entity_id,revision_id,visible_tier);
CREATE TABLE search_index_state(scope_id TEXT PRIMARY KEY, projection_version INTEGER NOT NULL, index_generation INTEGER NOT NULL, head_manifest_hash TEXT NOT NULL, dirty_ranges_json TEXT NOT NULL CHECK(json_valid(dirty_ranges_json)), coverage_json TEXT NOT NULL CHECK(json_valid(coverage_json)), visibility_epoch INTEGER NOT NULL, last_committed_seq INTEGER NOT NULL);
CREATE TABLE search_sessions(search_id TEXT PRIMARY KEY, view_id TEXT NOT NULL, query_seq INTEGER NOT NULL, scope_snapshot_id TEXT NOT NULL, index_generation INTEGER NOT NULL, visibility_epoch INTEGER NOT NULL, state_json TEXT NOT NULL CHECK(json_valid(state_json)));
CREATE TABLE progress_states(lesson_id TEXT PRIMARY KEY REFERENCES lessons(lesson_id), recording_id TEXT NOT NULL REFERENCES recording_sessions(recording_id), assignment_epoch INTEGER NOT NULL, calibration_seq INTEGER NOT NULL, decision_seq INTEGER NOT NULL, evidence_cutoff_ms INTEGER, body_json TEXT NOT NULL CHECK(json_valid(body_json)));
CREATE TABLE catchup_results(result_id TEXT PRIMARY KEY REFERENCES entities(entity_id), view_id TEXT NOT NULL, request_generation INTEGER NOT NULL, snapshot_id TEXT NOT NULL REFERENCES input_snapshots(snapshot_id), body_revision_id TEXT NOT NULL, body_json TEXT CHECK(body_json IS NULL OR json_valid(body_json)), body_evidence_cutoff_json TEXT NOT NULL CHECK(json_valid(body_evidence_cutoff_json)), progress_at_trigger_json TEXT NOT NULL CHECK(json_valid(progress_at_trigger_json)), progress_binding_json TEXT NOT NULL CHECK(json_valid(progress_binding_json)), completion_status TEXT NOT NULL CHECK(completion_status IN ('complete','partial','failed')), result_semantics TEXT NOT NULL CHECK(result_semantics IN ('focaus_context_v2','legacy_summary')), triggered_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE catchup_display_acks(result_id TEXT NOT NULL REFERENCES catchup_results(result_id), request_generation INTEGER NOT NULL, body_revision_id TEXT NOT NULL, elapsed_ms INTEGER NOT NULL CHECK(elapsed_ms>=0), displayed_complete INTEGER NOT NULL CHECK(displayed_complete IN (0,1)), PRIMARY KEY(result_id,request_generation));
CREATE TABLE settings(singleton INTEGER PRIMARY KEY CHECK(singleton=1), revision_id TEXT NOT NULL, body_json TEXT NOT NULL CHECK(json_valid(body_json)));
CREATE TABLE schedule_rules(schedule_id TEXT PRIMARY KEY REFERENCES entities(entity_id), course_id TEXT NOT NULL REFERENCES courses(course_id), body_json TEXT NOT NULL CHECK(json_valid(body_json)));
CREATE TABLE arrangements(arrangement_id TEXT PRIMARY KEY REFERENCES entities(entity_id), lesson_id TEXT NOT NULL REFERENCES lessons(lesson_id), kind TEXT NOT NULL, body_json TEXT NOT NULL CHECK(json_valid(body_json)));
INSERT INTO schema_migrations VALUES(1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
PRAGMA user_version=1;
COMMIT;
